; NeoV8 user interface: dispatcher, modes, timers, display/LED rendering.
; Behaviour reference: sim/src/proto/proto.ts (+ docs/ux-spec.md, spec/scenarios). Layout of the debug block
; and hardware adaptations: ui/README.md. Files: ui.asm (this), play.asm, edit.asm, menu.asm, store.asm,
; tables.asm, gen_tables.inc (generated by tools/gen-ui-tables.mjs).

UI_PLAY     = 0
UI_EDIT     = 1
UI_MENU     = 2
UI_TUNE     = 3
UI_CONFIRM  = 4
UI_RECEIVE  = 5
UI_SEQ      = 6             ; polysequencer page (ui/seq.asm)

UI_TM_ENT   = 0             ; timers
UI_TM_TCH   = 1
UI_TM_MSG   = 2
UI_TM_CHORD = 3

; times in control ticks (2.0485 ms)
UI_T_ENTRY  = 1953          ; 4.0 s number entry
UI_T_MSG    = 635           ; 1.3 s message
UI_T_CHORD  = 293           ; 0.6 s: EDIT then a digit = page jump (no key-up events on the 8279)
UI_BLINK_T  = 244           ; 500 ms blink period
UI_BLINK_ON = 146           ; 60 % on
UI_T_REDRAW = 64            ; periodic render (~130 ms) to follow changes made outside the UI


; Weak links: API the UI needs that other modules do not export yet (requested in the UI report).
.ifndef eng_lowest_held
eng_lowest_held:                    ; A = lowest held key (MIDI note) or $FF
        lda #$ff
        rts
.endif
.ifndef midi_dump_all
midi_dump_all:  STUBCALL $2D        ; A = parts (bit0 programs ...): background SysEx dump
.endif
.ifndef midi_rxall                  ; MIDI stub build: the variables the UI reads / writes
        .pushseg
        .bss
midi_rxall:     .res 1
midi_sxstat:    .res 1
midi_sxcount:   .res 1
midi_mon:       .res 3
        .popseg
.endif
.ifndef eng_mute
eng_mute:       STUBCALL $2C        ; A = 1 mute, 0 unmute (AUDIO MUTE)
.endif

.macro UIJ code, addr
        .byte code
        .word addr-1
.endmacro
.macro UIDISP tab
        lda #<tab
        sta ui_q
        lda #>tab
        sta ui_q+1
        jmp ui_dispatch
.endmacro
.macro UIFLASH str, blink
        ldx #<str
        ldy #>str
        lda #blink
        jsr ui_flash
.endmacro

; ================================================================== public entry points
ui_init:
        lda #$ff
        sta ui_ent
        sta ui_cmp
        sta ui_lt_par
        ldx #14
@p:     sta ui_pprev,x
        dex
        bpl @p
        lda #1
        sta ui_sel
        sta ui_sel+1
        jsr ui_nv_init              ; NeoV8 globals (first boot), undo slot
        lda NV_GLOBALS+G_POWERON
        beq @last
        lda #0
        beq @rec
@last:  lda NV_GLOBALS+G_LAST_STEP
        cmp #100
        bcc @rec
        lda #0
@rec:   jsr ui_recall_step_n        ; PERF, edit buffers
        jsr ui_engine               ; eng_apply_perf (applies both programs too)
        jsr ui_now
        lda ui_tn
        sta ui_last
        lda ui_tn+1
        sta ui_last+1
        jsr ui_render
        jmp panel_flush

; A = button code, X = raw 8279 byte (bit6 = 1 when A440 is up)
ui_key:
        sta ui_code
        sta ui_lastbtn
        ldy #0
        txa
        and #$40
        bne @up
        iny
@up:    sty ui_sh
        jsr ui_now
        lda #1
        sta ui_redraw
        lda ui_code
        cmp #BTN_A440TONE           ; matrix position of the A440 key (unconfirmed on hardware)
        bne @n1
        jmp ui_tone_toggle
@n1:    cmp #BTN_EDIT
        bne @n2
        jmp ui_edit_btn
@n2:    ; EDIT pressed less than 0.6 s ago: a digit jumps to a page (hardware stand-in for the EDIT+digit chord)
        lda ui_chord
        beq @n3
        lda #0
        sta ui_chord
        lda ui_code
        jsr ui_isdigit
        bcc @n3
        sta ui_d
        ldy #UI_TM_CHORD
        jsr ui_timer_expired
        bcs @n3
        lda ui_d
        ldx ui_chside
        jmp ui_jump_page
@n3:    lda ui_st_on
        beq @n4
        jmp ui_store_key
@n4:    ldx ui_mode
        lda ui_modekey_hi,x
        pha
        lda ui_modekey_lo,x
        pha
        rts
ui_modekey_lo:  .byte <(ui_play_key-1), <(ui_edit_key-1), <(ui_menu_key-1), <(ui_rts-1), <(ui_confirm_key-1), <(ui_receive_key-1), <(ui_seq_key-1)
ui_modekey_hi:  .byte >(ui_play_key-1), >(ui_edit_key-1), >(ui_menu_key-1), >(ui_rts-1), >(ui_confirm_key-1), >(ui_receive_key-1), >(ui_seq_key-1)

; X = pot index 0-14, A = 0-127
ui_pot:
        sta ui_pv
        sta ui_lastpot
        stx ui_pi
        jsr ui_now
        lda #1
        sta ui_redraw
        ldx ui_pi
        lda ui_pprev,x              ; previous position; unknown before the first report (as the prototype)
        cmp #$ff
        bne @k
        lda ui_pv
@k:     sta ui_pb
        lda ui_pv
        sta ui_pprev,x
        lda ui_mode
        cmp #UI_MENU
        bne @m1
        cpx #14
        bne ui_rts
        jmp ui_menu_pot
@m1:    cmp #UI_EDIT
        bne @m2
        jmp ui_edit_pot
@m2:    cmp #UI_SEQ
        bne @m3
        jmp ui_seq_pot
@m3:    cmp #UI_PLAY
        bne ui_rts
        jmp ui_play_pot

; MIDI program change: X = side, A = program number
ui_recall_prog:
        cmp #100
        bcs ui_rts
        pha
        txa
        and #1
        tax
        pla
        jsr ui_load_prog
        jmp ui_set_redraw

; MIDI program change to a step: A = step number
ui_recall_step:
        cmp #100
        bcs ui_rts
        jsr ui_recall_step_n
        jmp ui_set_redraw

; MIDI: a NeoV8 / UI-level SysEx was handled (globals stored, ...): nothing is cached, just redraw
ui_sysex_in:
ui_set_redraw:
        lda #1
        sta ui_redraw
ui_rts: rts

ui_service:
        jsr ui_engine
        jsr ui_now
        lda ui_tn
        sec
        sbc ui_last
        sta ui_a                    ; ticks elapsed (8 bit)
        lda ui_tn
        sta ui_last
        lda ui_tn+1
        sta ui_last+1
        lda ui_a
        bne @bl
        jmp @flush
@bl:    ; blink phase
        clc
        adc ui_blk
        bcc @b1
        adc #(256-UI_BLINK_T-1)     ; carry set: +256-244
@b1:    cmp #UI_BLINK_T
        bcc @b2
        sbc #UI_BLINK_T
@b2:    sta ui_blk
        ldx #0
        cmp #UI_BLINK_ON
        bcs @b3
        inx
@b3:    cpx ui_bon
        beq @b4
        inc ui_redraw
@b4:    lda seq_mode                ; sequencer state changed (first key, stop, events): show it now
        eor seq_run                 ; (a signature; a rare collision just waits for the periodic render)
        eor seq_free
        cmp ui_sq_sig
        beq @b5
        sta ui_sq_sig
        inc ui_redraw
@b5:    ; periodic render
        lda ui_rtick
        clc
        adc ui_a
        bcs @rt
        cmp #UI_T_REDRAW
        bcc @rt1
@rt:    inc ui_redraw
        lda #0
@rt1:   sta ui_rtick
        ; timers
        lda ui_ent
        bmi @t1
        ldy #UI_TM_ENT
        jsr ui_timer_expired
        bcc @t1
        lda #$ff
        sta ui_ent
        inc ui_redraw
@t1:    lda ui_tch_on
        beq @t2
        ldy #UI_TM_TCH
        jsr ui_timer_expired
        bcc @t2
        lda #0
        sta ui_tch_on
        inc ui_redraw
@t2:    lda ui_msg_on
        beq @t3
        ldy #UI_TM_MSG
        jsr ui_timer_expired
        bcc @t3
        lda #0
        sta ui_msg_on
        inc ui_redraw
@t3:    lda ui_chord
        beq @flush
        ldy #UI_TM_CHORD
        jsr ui_timer_expired
        bcc @flush
        lda #0
        sta ui_chord
@flush: lda ui_redraw
        beq @f2
        lda #0
        sta ui_redraw
        jsr ui_render
@f2:    lda panel_dirty
        beq @r
        jsr panel_flush
@r:     rts

; ================================================================== engine updates
; The engine re-applies both programs on eng_apply_prog (~30 ms with the real engine), so UI changes only mark
; what changed and ui_service makes one call per main-loop pass (same pass as the key / pot / MIDI event).
ui_apply_perf:
        lda #$80
        bne ui_apply_set
; X = side whose edit buffer changed
ui_apply_prog:
        lda #1
        cpx #0
        beq ui_apply_set
        asl
ui_apply_set:
        ora ui_eng
        sta ui_eng
        rts

ui_engine:
        lda ui_eng
        beq @r0
        ldx #0
        stx ui_eng
        pha
        jsr ui_engine_apply
        pla
        and #$40                    ; a program was recalled: envelopes idle, kbd CV/gate cleared
        beq @r0
        jmp eng_recalled
@r0:    rts
ui_engine_apply:
        asl
        bcc @prog
        jmp eng_apply_perf          ; PERF changed (the engine re-applies the programs too)
@prog:  lsr
        lsr
        bcc @l
        pha
        ldx #0
        jsr eng_apply_prog
        pla
        lsr
        bcc @r
        ldx #1
        jmp eng_apply_prog
@l:     lsr
        bcc @r
        ldx #1
        jmp eng_apply_prog
@r:     rts

; ================================================================== time
; ticks -> ui_tn (the IRQ may change it between the two byte reads)
ui_now:
        lda ticks+1
        ldx ticks
        cmp ticks+1
        bne ui_now
        stx ui_tn
        sta ui_tn+1
        rts

; Y = timer, A/X = duration lo/hi (ticks) from ui_tn
ui_timer_set:
        clc
        adc ui_tn
        sta ui_dl_lo,y
        txa
        adc ui_tn+1
        sta ui_dl_hi,y
        rts

; Y = timer -> C=1 when ui_tn has passed the deadline
ui_timer_expired:
        lda ui_dl_lo,y
        cmp ui_tn
        lda ui_dl_hi,y
        sbc ui_tn+1                 ; deadline - now
        bmi @yes
        clc
        rts
@yes:   sec
        rts

; ================================================================== small helpers
; A = button code -> C=1 and A = digit 0-9 when it is a keypad digit
ui_isdigit:
        sec
        sbc #BTN_0
        cmp #10
        bcs @no
        sec
        rts
@no:    clc
        rts

; jump through the table at ui_q: rows [code, .word handler-1], terminated by $FF + fallback handler
ui_dispatch:
        ldy #0
@l:     lda (ui_q),y
        cmp #$ff
        beq @hit
        cmp ui_code
        beq @hit
        iny
        iny
        iny
        bne @l
@hit:   iny
        iny
        lda (ui_q),y
        pha
        dey
        lda (ui_q),y
        pha
        rts

; A = side -> ui_buf = edit buffer, ui_bside
ui_setbuf:
        and #1
        sta ui_bside
        beq @r
        lda #<EDIT_L
        bne @s
@r:     lda #<EDIT_R
@s:     sta ui_buf
        lda #>EDIT_R
        sta ui_buf+1
        rts

; X = param -> A = raw value (ui_buf). X preserved.
ui_pget:
        ldy ui_p_byte,x
        lda (ui_buf),y
        ldy ui_p_shift,x
        beq @m
@s:     lsr
        dey
        bne @s
@m:     and ui_p_mask,x
        rts

; X = param, A = raw value -> ui_buf. X preserved.
ui_pset:
        and ui_p_mask,x
        ldy ui_p_shift,x
        beq @n
@s:     asl
        dey
        bne @s
@n:     sta ui_a
        ldy ui_p_byte,x
        lda ui_p_smask,x
        eor #$ff
        and (ui_buf),y
        ora ui_a
        sta (ui_buf),y
        rts

; X = param -> A = raw value meaning ON (ui_onw if set, else 0 for active-low flags, 1 otherwise)
ui_onval:
        lda ui_onw
        bpl @r
        lda ui_p_flags,x
        asl                         ; C = active low
        lda #0
        bcs @r
        lda #1
@r:     rts

; X = param -> C=1 when ON
ui_ison:
        jsr ui_onval
        sta ui_c
        jsr ui_pget
        cmp ui_c
        beq @y
        clc
        rts
@y:     sec
        rts

; A * X -> ui_mh:ui_ml
ui_mul8:
        sta ui_ml
        stx ui_mh
        lda #0
        ldx #8
        lsr ui_ml
@l:     bcc @n
        clc
        adc ui_mh
@n:     ror
        ror ui_ml
        dex
        bne @l
        sta ui_mh
        rts

; ui_mh:ui_ml / X (ui_mh < X) -> A = quotient, ui_mh = remainder
ui_div16:
        stx ui_c
        ldx #8
        lda ui_mh
@l:     asl ui_ml
        rol
        bcs @sub
        cmp ui_c
        bcc @n
@sub:   sbc ui_c
        inc ui_ml
@n:     dex
        bne @l
        sta ui_mh
        lda ui_ml
        rts

; A / X -> A quotient, ui_mh remainder
ui_div8:
        sta ui_ml
        lda #0
        sta ui_mh
        jmp ui_div16

; A = 0-127, X = n -> A = round(A * n / 127)
ui_scale:
        jsr ui_mul8
        lda ui_ml
        clc
        adc #63
        sta ui_ml
        bcc @c
        inc ui_mh
@c:     ldx #127
        jmp ui_div16

; A (0-255) -> ui_a hundreds, ui_b tens, A units. Y preserved.
ui_dec3:
        ldx #0
@h:     cmp #100
        bcc @t0
        sbc #100
        inx
        bne @h
@t0:    stx ui_a
        ldx #0
@t:     cmp #10
        bcc @u
        sbc #10
        inx
        bne @t
@u:     stx ui_b
        rts

; ---- text builder ui_tx (Y = position)
ui_tx_blank:
        ldy #5
        lda #' '
@l:     sta ui_tx,y
        dey
        bpl @l
        iny
        rts

; A = 0-99 -> two digits at Y, Y += 2
ui_tx_2d:
        jsr ui_dec3
        pha
        lda ui_b
        ora #'0'
        sta ui_tx,y
        iny
        pla
        ora #'0'
        sta ui_tx,y
        iny
        rts

; A -> two hex digits at Y, Y += 2
ui_tx_hex:
        pha
        lsr
        lsr
        lsr
        lsr
        jsr panel_hexdigit
        sta ui_tx,y
        iny
        pla
        jsr panel_hexdigit
        sta ui_tx,y
        iny
        rts

; X/Y = 6-char text, A = blink -> message for 1.3 s
ui_flash:
        sta ui_msg_blk
        stx ui_p
        sty ui_p+1
        ldy #5
@l:     lda (ui_p),y
        sta ui_tx,y
        dey
        bpl @l
        lda ui_msg_blk
; ui_tx -> message (A = blink), no decimal points
ui_flash_tx:
        ldx #0
        stx ui_msg_dp
; same with X = decimal points
ui_flash_txdp:
        sta ui_msg_blk
        stx ui_msg_dp
        ldy #5
@l:     lda ui_tx,y
        sta ui_msg_txt,y
        dey
        bpl @l
        lda #1
        sta ui_msg_on
        lda #<UI_T_MSG
        ldx #>UI_T_MSG
        ldy #UI_TM_MSG
        jmp ui_timer_set

; ui_tx -> value-on-touch for the display-hold time (menu 32)
ui_touch_tx:
        ldy #5
@l:     lda ui_tx,y
        sta ui_tch_txt,y
        dey
        bpl @l
        lda #1
        sta ui_tch_on
        lda NV_GLOBALS+G_DISPHOLD
        cmp #5
        bcs @a
        lda #5
@a:     cmp #31
        bcc @b
        lda #30
@b:     ldx #49                     ; x100 ms in ticks: x * 49 * (1 - 1/256) = x * 48.81
        jsr ui_mul8
        lda ui_ml
        sec
        sbc ui_mh
        tay
        lda ui_mh
        sbc #0
        tax
        tya
        ldy #UI_TM_TCH
        jmp ui_timer_set

; X = param, ui_buf = side, ui_onw = ON value or $FF, ui_mark = pickup marker -> touch display "mn" + value
ui_touch_param:
        stx ui_lt_par
        lda ui_bside
        sta ui_lt_side
        jsr ui_tx_blank
        lda ui_p_mn0,x
        sta ui_tx
        lda ui_p_mn1,x
        sta ui_tx+1
        lda ui_p_flags,x
        and #7
        beq @nenum
        ldy #4                      ; enum: "  " + text
        jsr ui_enum_at
        ldx ui_lt_par
        jmp @mark
@nenum: lda ui_p_mask,x
        cmp #1
        bne @num
        jsr ui_ison                 ; flag: "  On" / " OFF"
        bcc @off
        lda #'O'
        sta ui_tx+4
        lda #'n'
        sta ui_tx+5
        bne @mark
@off:   lda #'O'
        sta ui_tx+3
        lda #'F'
        sta ui_tx+4
        sta ui_tx+5
        bne @mark
@num:   jsr ui_pget                 ; number, 3 chars right aligned
        jsr ui_tx_num3
@mark:  lda ui_mark
        sta ui_tx+2
        jmp ui_touch_tx

; A = 0-255 -> right-aligned at ui_tx+3..5
ui_tx_num3:
        jsr ui_dec3
        ora #'0'
        sta ui_tx+5
        lda ui_a
        beq @t
        ora #'0'
        sta ui_tx+3
        lda ui_b
        ora #'0'
        sta ui_tx+4
        rts
@t:     lda ui_b
        beq @r
        ora #'0'
        sta ui_tx+4
@r:     rts

; reset the pickup state (page / side / program change)
ui_uncatch:
        lda #0
        sta ui_caught
        sta ui_caught+1
        sta ui_caught+2
        sta ui_caught+3
        rts

; ================================================================== EDIT button (acts on press)
ui_edit_btn:
        lda ui_sh
        beq @n0
        lda #10                     ; A440+EDIT: SYSTEM menu
        jmp ui_menu_enter
@n0:    lda #0
        sta ui_chord
        lda ui_st_on
        beq @n1
        lda #0                      ; cancel a store in progress
        sta ui_st_on
        UIFLASH ui_s_cancel, 0
        rts
@n1:    lda ui_ent
        bmi @n2
        ldx #$ff
        stx ui_ent
        ldx ui_ent_n
        beq @n2                     ; right after CALL: EDIT simply enters edit
        rts                         ; EDIT cancels a half-typed number
@n2:    lda ui_mode
        cmp #UI_PLAY
        bne @n3
        ldx ui_focus                ; PLAY -> EDIT on the focused side, last page of that side
        cpx #1
        beq @s
        ldx #0
@s:     stx ui_eside
        lda ui_lastpg,x
        sta ui_page
        lda #UI_EDIT
        sta ui_mode
        jsr ui_uncatch
        ldx ui_eside
        jmp @chord
@n3:    cmp #UI_EDIT
        bne @n4
        ldx ui_eside                ; EDIT -> PLAY
        lda ui_page
        sta ui_lastpg,x
        lda #UI_PLAY
        sta ui_mode
        jsr ui_uncatch
        jsr ui_compare_off
        ldx ui_eside
        jmp @chord
@n4:    cmp #UI_TUNE
        beq @r
        cmp #UI_SEQ
        bne @n5
        lda #UI_PLAY                ; sequencer page -> PLAY
        sta ui_mode
        bne @foc
@n5:    jsr ui_pop_mode             ; menu / confirm / receive: back
        jsr ui_receive_off
        ldx ui_eside
        lda ui_mode
        cmp #UI_EDIT
        beq @chord
@foc:   ldx ui_focus
        cpx #1
        beq @chord
        ldx #0
@chord: stx ui_chside               ; arm the EDIT+digit page jump
        lda #1
        sta ui_chord
        lda #<UI_T_CHORD
        ldx #>UI_T_CHORD
        ldy #UI_TM_CHORD
        jmp ui_timer_set
@r:     rts

; A = overlay mode (menu, confirm, receive, tune): enter it, remembering where to come back (2 levels,
; e.g. the menu opened over the SysEx receive page)
ui_push_mode:
        ldx ui_back
        stx ui_back2
        ldx ui_mode
        stx ui_back
        sta ui_mode
        rts
ui_pop_mode:
        lda ui_back
        sta ui_mode
        lda ui_back2
        sta ui_back
        rts

; A = digit 1-6, X = side: edit that page (EDIT+digit, A440+digit in EDIT)
ui_jump_page:
        sec
        sbc #1
        cmp #UI_NPAGES
        bcs @r
        sta ui_page
        stx ui_eside
        lda #UI_EDIT
        sta ui_mode
        jsr ui_uncatch
@r:     rts

; A440+AUTO TUNE (or the A440 key itself): reference tone on PTM T3 (stock $F1B2: 2e6 / (2*2273) = 439.9 Hz)
ui_tone_toggle:
        lda ui_tone
        eor #1
        sta ui_tone
        php
        sei
        tax
        beq @off
        lda #$08
        sta PTM_T3MSB
        lda #$e0
        sta PTM_T3LSB
        lda #$82                    ; CR3 (CR2 bit 0 = 0): output on, internal clock
        bne @w
@off:   lda #$02
@w:     sta PTM_CR13
        plp
        rts

        .include "ui/play.asm"
        .include "ui/edit.asm"
        .include "ui/menu.asm"
        .include "ui/store.asm"
        .include "ui/seq.asm"
        .include "ui/render.asm"
        .include "ui/tables.asm"
        .include "ui/gen_tables.inc"
